-- ----------------------------
-- Table structure for food_category
-- ----------------------------
DROP TABLE IF EXISTS `food_category`;
CREATE TABLE `food_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(50) DEFAULT '' COMMENT '分类名称',
  `order_num` int DEFAULT '0' COMMENT '显示顺序',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='美食分类表';

INSERT INTO `food_category` (`id`, `name`, `order_num`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES ('100','川菜','1','0','admin','2026-09-15 10:11:05','',NULL,'麻辣鲜香，一菜一格'),('101','粤菜','2','0','admin','2026-09-15 10:11:05','',NULL,'清而不淡，鲜而不俗'),('102','鲁菜','3','0','admin','2026-09-15 10:11:05','',NULL,'咸鲜为主，火候见长'),('103','甜品','4','0','admin','2026-09-15 10:11:05','',NULL,'饭后一口，心情变甜'),('104','小吃','5','0','admin','2026-09-15 10:11:05','',NULL,'街头巷尾的烟火气'),('105','湘菜','6','0','admin','2026-09-15 10:11:05','',NULL,'香辣浓郁，无辣不欢'),('106','家常菜','7','0','admin','2026-09-15 10:11:05','',NULL,'一日三餐，家的味道'),('107','汤羹','8','0','admin','2026-09-15 10:11:05','',NULL,'一碗热汤，暖胃暖心'),('108','面食','9','0','admin','2026-09-15 10:11:05','',NULL,'面香扑鼻，碳水快乐'),('109','饮品','10','0','admin','2026-09-15 10:11:05','',NULL,'解腻解辣，随手一杯'),('110','素食','11','0','admin','2026-09-15 10:11:05','',NULL,'清爽少负担'),('111','烘焙','12','0','admin','2026-09-15 10:11:05','',NULL,'烤箱里的香气');


-- ----------------------------
-- Table structure for food_comment
-- ----------------------------
DROP TABLE IF EXISTS `food_comment`;
CREATE TABLE `food_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `food_id` bigint NOT NULL COMMENT '美食ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `content` varchar(500) DEFAULT '' COMMENT '评论内容',
  `parent_id` bigint DEFAULT '0' COMMENT '父评论ID（回复用）',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '评论时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_food_id` (`food_id`)
) ENGINE=InnoDB AUTO_INCREMENT=70667 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='美食评论表';

