-- ----------------------------
-- Table structure for food_info
-- ----------------------------
DROP TABLE IF EXISTS `food_info`;
CREATE TABLE `food_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '美食ID',
  `category_id` bigint DEFAULT NULL COMMENT '分类ID',
  `title` varchar(100) DEFAULT '' COMMENT '美食标题',
  `image` varchar(255) DEFAULT '' COMMENT '封面图片',
  `description` varchar(500) DEFAULT '' COMMENT '简介',
  `content` text COMMENT '详细内容',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `favorite_count` int DEFAULT '0' COMMENT '收藏数',
  `comment_count` int DEFAULT '0' COMMENT '评论数',
  `status` char(1) DEFAULT '0' COMMENT '状态（0发布 1下架）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='美食信息表';

INSERT INTO `food_info` (`id`, `category_id`, `title`, `image`, `description`, `content`, `like_count`, `favorite_count`, `comment_count`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES ('100','100','麻婆豆腐','/profile/upload/seed/dish_ad19ef128cd3.jpg','麻辣鲜香，下饭神器11111','经典川菜，豆腐嫩滑，麻辣鲜香，是川菜中的代表作。','14','6','4','0','admin','2026-09-15 03:38:51','admin','2026-09-16 08:31:09',''),('101','100','宫保鸡丁','/profile/upload/seed/dish_268ca7407944.jpg','酸甜微辣，鸡肉嫩滑','川菜代表，花生酥脆，鸡肉鲜嫩，酸甜微辣。','16','9','5','0','admin','2026-09-15 03:38:51','',NULL,''),('102','101','白切鸡','/profile/upload/seed/dish_1487405eaab0.jpg','皮爽肉滑，原汁原味','粤菜经典，皮爽肉滑，蘸料提鲜。','19','9','6','0','admin','2026-09-15 03:38:51','',NULL,''),('103','102','红烧肉','/profile/upload/seed/dish_103.jpg','肥而不腻，入口即化','鲁菜代表，色泽红亮，软糯香甜，肥而不腻。','18','10','9','0','admin','2026-09-15 03:38:51','',NULL,''),('104','103','提拉米苏','/profile/upload/seed/dish_104.jpg','咖啡与奶油的完美结合','意式甜点，咖啡与奶油的完美结合，入口即化。','15','9','9','0','admin','2026-09-15 03:38:51','',NULL,''),('105','104','小笼包','/profile/upload/seed/dish_d1c97d8b6daf.jpg','皮薄馅多，汤汁鲜美','江南特色小吃，皮薄馅多，先开窗后喝汤。','19','7','11','0','admin','2026-09-15 03:38:51','',NULL,''),('111','101','水晶包','/profile/upload/seed/dish_111.jpg','皮薄肉多，汁水多，食材新鲜','地址：广东','16','9','11','0','admin','2026-09-15 17:43:59','admin','2026-09-15 19:42:18',''),('200','100','麻婆豆腐','/profile/upload/seed/dish_200.jpg','麻辣鲜香，下饭神器','豆腐嫩滑、牛肉臊子酥香，一勺红油盖住整碗米饭。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。','15','6','8','0','admin','2026-08-26 10:11:05','',NULL,''),('201','100','宫保鸡丁','/profile/upload/seed/dish_201.jpg','酸甜微辣，鸡肉嫩滑','鸡丁滑嫩、花生酥脆，糖醋汁收得亮亮的。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。','16','7','5','0','admin','2026-08-25 10:11:05','',NULL,''),('202','100','回锅肉','/profile/upload/seed/dish_e4e758f6e2e2.jpg','肥而不腻，川菜之首','二刀肉先煮后炒，郫县豆瓣炒出红油，蒜苗一拌香气冲鼻。\n\n小贴士：食材提前备齐，火候宁小勿大，出锅前再调味。','18','9','6','0','chuancai','2026-08-24 10:11:05','',NULL,''),('203','100','水煮鱼','/profile/upload/seed/dish_b9f6aa0564e5.jpg','麻辣鲜烫，鱼片嫩滑','鱼片薄而不断，热油泼在花椒辣椒上的一瞬间最香