-- ----------------------------
-- Table structure for food_like
-- ----------------------------
DROP TABLE IF EXISTS `food_like`;
CREATE TABLE `food_like` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '点赞ID',
  `food_id` bigint NOT NULL COMMENT '美食ID',
